const mount=document.querySelector('#app');const modal=document.querySelector('#dialog');
if(!(mount instanceof HTMLElement)||!(modal instanceof HTMLDialogElement))throw new Error('Missing application container');
const app=mount;const dialog=modal;
let activeView='list';let filter='all';let query='';let currentId='';let monthKey='';let importing=false;
/** @type {HTMLElement|null} */let lastFocus=null;
function current(){return resumes.find(r=>r.id===currentId);}
function render(){const focused=document.activeElement;const action=focused instanceof HTMLButtonElement?focused.dataset.action:null;const id=focused instanceof HTMLButtonElement?focused.dataset.id:null;const r=current();app.innerHTML=(storageMessage?`<div class="error" role="alert">${esc(storageMessage)}</div>`:'')+(activeView==='list'||!r?listView():activeView==='preview'?previewView(r):editorView(r));if(action){const next=[...app.querySelectorAll('button')].find(b=>b.dataset.action===action&&b.dataset.id===id);next?.focus({preventScroll:true});}}
/** @param {string} next */
function go(next){activeView=next;render();window.scrollTo(0,0);const heading=app.querySelector('h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}
/** @param {string} title @param {string} body */
function showDialog(title,body){if(!dialog.open){lastFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;}dialog.innerHTML=`<div class="dialog-content"><div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2>${button('close-dialog','닫기','quiet')}</div>${body}</div>`;dialog.setAttribute('aria-labelledby','dialog-title');if(!dialog.open)dialog.showModal();}
function closeDialog(){dialog.close();if(lastFocus?.isConnected)lastFocus.focus();}
/** @param {Resume} r */
function changed(r){r.updated=new Date().toISOString();const ok=persist();const status=document.querySelector('.saved');if(status)status.textContent=ok?'브라우저에 저장됨':'저장하지 못함 · 백업 필요';const title=document.querySelector('.doc-title');if(title)title.textContent=r.title;let alert=document.querySelector('.error');if(storageMessage&&!alert){app.insertAdjacentHTML('afterbegin',`<div class="error" role="alert">${esc(storageMessage)}</div>`);}else if(!storageMessage)alert?.remove();}
/** @param {string} name @param {unknown} data */
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
/** @param {string} value */
function setMonth(value){const r=current();if(!r)return;const [key,index,part]=monthKey.split('.');if(part!=='start'&&part!=='end')return;if(key==='experience'&&r.experience[Number(index)])r.experience[Number(index)][part]=value;if(key==='education'&&r.education[Number(index)])r.education[Number(index)][part]=value;changed(r);closeDialog();render();const control=document.querySelector(`[data-month-key="${monthKey}"]`);if(control instanceof HTMLElement)control.focus();}
function historyView(){const r=current();if(!r)return;showDialog('버전 기록',`<p class="small">복원하기 전에 현재 내용을 안전 버전으로 남겨요.</p>${r.versions.length?r.versions.map(v=>`<article class="version"><h3>${esc(v.label)}</h3><p class="small">${dateLabel(v.date)}</p><div class="version-actions">${button('compare','현재와 비교','',`data-version="${v.id}"`)}${button('restore','이 버전 복원','',`data-version="${v.id}"`)}</div></article>`).join(''):'<p class="section-empty">저장한 버전이 없어요. 중요한 수정 전에 버전을 남겨보세요.</p>'}`);}
/** @param {Content} c @param {string[]} sections */
function compareContent(c,sections){const values=[['기본 정보',[c.title,c.target,c.name,c.email,c.phone,c.link].filter(Boolean).join('\n')],['소개',c.summary],['경력',c.experience.map(e=>[e.company,e.role,period(e.start,e.end,'재직 중'),e.description].join('\n')).join('\n\n')],['학력',c.education.map(e=>[e.school,e.major,period(e.start,e.end,'재학 중')].join('\n')).join('\n\n')],['스킬',c.skills],['지원 공고',c.job]];return values.filter(([label])=>sections.includes(label)).map(([label,value])=>`<h4>${label}</h4><p>${esc(value||'작성된 내용 없음')}</p>`).join('');}
/** @param {string} id @param {boolean} all */
function showCompare(id,all=false){const r=current();const v=r?.versions.find(x=>x.id===id);if(!r||!v)return;const diff=changes(v.content,contentOf(r));const sections=all?['기본 정보','소개','경력','학력','스킬','지원 공고']:diff;showDialog('버전 비교',`<p class="small">${diff.length?`달라진 항목: ${diff.join(', ')}`:'내용이 같아요.'}</p>${sections.length?`<div class="compare"><div><h3>${esc(v.label)}</h3>${compareContent(v.content,sections)}</div><div><h3>현재 작성 내용</h3>${compareContent(r,sections)}</div></div>`:''}<div class="dialog-actions">${button(all?'compare':'compare-all',all?'변경 항목만 보기':'전체 내용 보기','',`data-version="${v.id}"`)}</div>`);}
function reviewDraft(){const r=current();if(!r)return;const checks=[r.name.trim()?'이름 입력됨':'이름을 입력해 주세요.',/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.email)?'이메일 형식 확인됨':'연락받을 이메일 형식을 확인해 주세요.',r.summary.trim()?'소개 입력됨':'소개를 작성해 주세요.',r.experience.length?'경력·프로젝트 입력됨':'경력이나 프로젝트를 추가해 보세요.',...r.experience.flatMap((e,i)=>[...(!e.company.trim()?[`경력 ${i+1}: 회사·프로젝트명을 입력해 주세요.`]:[]),...(e.end&&e.start>e.end?[`경력 ${i+1}: 시작월이 종료월보다 늦어요.`]:[])]),...r.education.flatMap((e,i)=>e.end&&e.start>e.end?[`학력 ${i+1}: 시작월이 종료월보다 늦어요.`]:[])];showDialog('작성 점검',`<p class="small">입력 누락과 날짜 형식을 확인해요. 채용 평가 점수는 아니에요.</p><ul class="checks">${checks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`);}
function matchJob(){const r=current();if(!r)return;if(!r.job.trim()){showDialog('공고와 대조','<p>지원 준비 항목에 채용공고 요구사항을 붙여 넣어 주세요.</p>');return;}const skills=r.skills.split(',').map(s=>s.trim()).filter(Boolean);const found=skills.filter(s=>r.job.toLowerCase().includes(s.toLowerCase()));showDialog('공고와 대조',`<p>작성한 스킬 중 공고에 같은 표현이 있는 항목을 찾아요. 동의어나 경험의 깊이를 평가하지 않아요.</p><div class="skill-list" style="margin-top:var(--s5)">${found.length?found.map(s=>`<span>${esc(s)}</span>`).join(''):'<span>일치하는 스킬 표현 없음</span>'}</div><h3 style="margin-top:var(--s6)">지원 전 확인</h3><ul class="checks"><li>공고의 핵심 업무를 맡았던 경험이 소개와 경력에 드러나나요?</li><li>성과 수치와 기여 내용에 실제 근거가 있나요?</li><li>지원처에 맞춰 복제한 이력서인지 확인했나요?</li></ul>`);}
/** @param {Event} event */
function clickHandler(event){if(!(event.target instanceof Element))return;const target=event.target.closest('button');if(!target)return;if(target.dataset.filter){filter=target.dataset.filter;render();const control=document.querySelector(`[data-filter="${filter}"]`);if(control instanceof HTMLElement)control.focus();return;}const r=current();const selected=resumes.find(x=>x.id===target.dataset.id);switch(target.dataset.action){case'month':{monthKey=target.dataset.monthKey||'';const value=target.dataset.monthValue||'';showDialog('연월 선택',`<form id="month-form"><div class="fields"><label class="field"><span>연도</span><input name="year" type="number" min="1900" max="2100" required value="${value.slice(0,4)||new Date().getFullYear()}"></label><label class="field"><span>월</span><select name="month" aria-label="월">${Array.from({length:12},(_,i)=>`<option value="${String(i+1).padStart(2,'0')}" ${Number(value.slice(5))===i+1?'selected':''}>${i+1}월</option>`).join('')}</select></label></div><div class="dialog-actions">${button('clear-month','선택 해제')}<button type="submit" class="button primary">적용</button></div></form>`);break;}case'clear-month':setMonth('');break;case'new':{const doc=newResume('새 이력서');resumes.unshift(doc);persist();currentId=doc.id;go('edit');break;}case'edit':if(selected){currentId=selected.id;go('edit');}break;case'edit-current':go('edit');break;case'list':go('list');break;case'preview':go('preview');break;case'clear-search':query='';render();break;case'duplicate':if(selected){const copy={...structuredClone(selected),id:crypto.randomUUID(),title:`${selected.title} · 복사본`,status:'draft',archived:false,updated:new Date().toISOString(),versions:[]};resumes.unshift(copy);persist();filter='all';render();}break;case'archive':if(selected){selected.archived=!selected.archived;changed(selected);render();}break;case'add-experience':if(r){r.experience.push({company:'',role:'',start:'',end:'',description:''});changed(r);render();document.querySelector('#experience .entry:last-child input')?.scrollIntoView({block:'center'});}break;case'add-education':if(r){r.education.push({school:'',major:'',start:'',end:''});changed(r);render();document.querySelector('#education .entry:last-child input')?.scrollIntoView({block:'center'});}break;case'remove-experience':case'remove-education':if(r){snapshot(r,'항목 삭제 전 자동 보관');if(target.dataset.action==='remove-experience')r.experience.splice(Number(target.dataset.index),1);else r.education.splice(Number(target.dataset.index),1);changed(r);render();}break;case'save-version':showDialog('버전 저장',`<form id="version-form"><label class="field"><span>버전 이름</span><input name="label" required maxlength="80" placeholder="예: 커머스 지원 전"></label><div class="dialog-actions"><button type="submit" class="button primary">저장</button></div></form>`);break;case'history':historyView();break;case'compare':showCompare(target.dataset.version||'');break;case'compare-all':showCompare(target.dataset.version||'',true);break;case'restore':if(r){const v=r.versions.find(x=>x.id===target.dataset.version);if(v){const data=structuredClone(v.content);snapshot(r,'복원 전 자동 보관');Object.assign(r,data);changed(r);closeDialog();render();}}break;case'close-dialog':closeDialog();break;case'review':reviewDraft();break;case'match':matchJob();break;case'print':window.print();break;case'backup':if(r)download('resume-backup.json',[r]);break;case'backup-all':download('resumes-backup.json',resumes);break;case'import':{const input=document.querySelector('#import-file');if(input instanceof HTMLInputElement)input.click();break;}}}
app.addEventListener('click',clickHandler);dialog.addEventListener('click',clickHandler);dialog.addEventListener('cancel',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
dialog.addEventListener('submit',event=>{event.preventDefault();if(!(event.target instanceof HTMLFormElement))return;const r=current();if(!r)return;const form=new FormData(event.target);if(event.target.id==='month-form'){setMonth(`${form.get('year')}-${form.get('month')}`);return;}const label=String(form.get('label')||'').trim();if(!label)return;snapshot(r,label);changed(r);closeDialog();});
app.addEventListener('input',event=>{const input=event.target;if(!(input instanceof HTMLInputElement||input instanceof HTMLTextAreaElement))return;if(input.id==='search'){query=input.value;const cards=document.querySelector('#cards');if(cards)cards.innerHTML=cardsView();return;}const r=current();if(!r||!input.dataset.field)return;const [key,index,part]=input.dataset.field.split('.');if(key==='experience'){const e=r.experience[Number(index)];if(e&&['company','role','start','end','description'].includes(part))Reflect.set(e,part,input.value);}else if(key==='education'){const e=r.education[Number(index)];if(e&&['school','major','start','end'].includes(part))Reflect.set(e,part,input.value);}else if(['title','target','name','email','phone','link','summary','skills','job'].includes(key))Reflect.set(r,key,input.value);changed(r);});
app.addEventListener('change',event=>{const input=event.target;if(input instanceof HTMLSelectElement&&input.hasAttribute('data-status')){const r=current();if(r){r.status=input.value;changed(r);}}if(input instanceof HTMLInputElement&&input.id==='import-file')void importBackup(input);});
/** @param {HTMLInputElement} input */
async function importBackup(input){const file=input.files?.[0];if(!file||importing)return;importing=true;const trigger=app.querySelector('[data-action="import"]');if(trigger instanceof HTMLButtonElement){trigger.disabled=true;trigger.textContent='불러오는 중';}try{if(file.size>5000000)throw new Error('large');const parsed=backupSchema.min(1).parse(JSON.parse(await file.text()));const restored=parsed.map(r=>({...r,id:crypto.randomUUID(),title:`${r.title} · 불러옴`}));resumes.unshift(...restored);persist();filter='all';query='';render();}catch{showDialog('불러올 수 없어요','<p>이 작업실에서 내려받은 5MB 이하의 이력서 백업 파일을 선택해 주세요.</p>');}finally{importing=false;const trigger=app.querySelector('[data-action="import"]');if(trigger instanceof HTMLButtonElement){trigger.disabled=false;trigger.textContent='백업 불러오기';}}}
if(new URLSearchParams(location.search).get('new')==='1'){const doc=newResume('새 이력서');resumes.unshift(doc);currentId=doc.id;activeView='edit';history.replaceState(null,'',location.pathname);}
if(!storageMessage)persist();
render();

window.addEventListener('scroll',()=>{if(activeView!=='edit')return;const sections=[...app.querySelectorAll('.document-section')];const active=sections.filter(s=>s.getBoundingClientRect().top<=160).at(-1)||sections[0];for(const link of app.querySelectorAll('.section-nav a')){if(link.getAttribute('href')===`#${active?.id}`)link.setAttribute('aria-current','true');else link.removeAttribute('aria-current');}},{passive:true});
